132	CHRPOS BlockMgr::getTotalBlockLength(RecordKeyVector &keyList) {
133		CHRPOS sum = 0;
134		for (RecordKeyVector::iterator_type iter = keyList.begin(); iter != keyList.end(); iter = keyList.next()) {
135			const Record *record = *iter;
136			sum += record->getEndPos() - record->getStartPos();
137		}
138		return sum;
139	}
140	
141	void BlockMgr::deleteBlocks(RecordKeyVector &keyList)
142	{
143		for (RecordKeyVector::iterator_type iter = keyList.begin(); iter != keyList.end(); iter = keyList.next()) {
144			_blockRecordsMgr->deleteRecord(*iter);
145		}
146		keyList.clearVector();
147	}
