149	int BlockMgr::findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
150		                              RecordKeyVector &resultList, RecordKeyVector *overlapList)
151	{
152		bool deleteKeyBlocks = false;
153		if (keyList.empty()) {
154			//get all the blocks for the query record, put them in it's list.
155			getBlocks(keyList, deleteKeyBlocks);
156		}
157		_overlapBases.clear();
158		CHRPOS keyBlocksSumLength = getTotalBlockLength(keyList);
159	
160		//Loop through every database record the query intersected with
161		RecordKeyVector::iterator_type hitListIter = hitList.begin();
162		for (; hitListIter != hitList.end(); hitListIter = hitList.next())
163		{
164			RecordKeyVector hitBlocks(*hitListIter);
165			bool deleteHitBlocks = false;
166			getBlocks(hitBlocks, deleteHitBlocks); //get all blocks for the hit record.
167			CHRPOS hitBlockSumLength = getTotalBlockLength(hitBlocks); //get total length of the bocks for the hitRecord.
168			CHRPOS totalHitOverlap = 0;
169			bool hitHasOverlap = false;
170	
171			//loop through every block of the database record.
172			RecordKeyVector::iterator_type hitBlockIter = hitBlocks.begin();
173			for (; hitBlockIter != hitBlocks.end(); hitBlockIter = hitBlocks.next()) 
174			{
175				//loop through every block of the query record.
176				RecordKeyVector::iterator_type keyListIter = keyList.begin();
177				for (; keyListIter != keyList.end(); keyListIter = keyList.next()) 
178				{
179					const Record *keyBlock = *keyListIter;
180					const Record *hitBlock = *hitBlockIter;
181	
182					CHRPOS maxStart = max(keyBlock->getStartPos(), hitBlock->getStartPos());
183					CHRPOS minEnd = min(keyBlock->getEndPos(), hitBlock->getEndPos());
184					CHRPOS overlap  = minEnd - maxStart;
185					if (overlap > 0) {
186						hitHasOverlap = true;
187						if (overlapList != NULL) {
188							overlapList->push_back(allocateAndAssignRecord(keyList.getKey(), maxStart, minEnd));
189						}
190						totalHitOverlap += overlap;
191					}
192				}
193			}
194			if (hitHasOverlap) {
195				if ((float) totalHitOverlap / (float)keyBlocksSumLength >= _overlapFraction) {
196					if (_hasReciprocal &&
197							((float)totalHitOverlap / (float)hitBlockSumLength >= _overlapFraction)) {
198						_overlapBases.push_back((int)totalHitOverlap);
199						resultList.push_back(*hitListIter);
200					} else if (!_hasReciprocal) {
201						_overlapBases.push_back((int)totalHitOverlap);
202						resultList.push_back(*hitListIter);
203					}
204				}
205			}
206			if (deleteHitBlocks) {
207				deleteBlocks(hitBlocks);
208			}
209		}
210		if (deleteKeyBlocks) {
211			deleteBlocks(keyList);
212		}
213		resultList.setKey(keyList.getKey());
214		return (int)resultList.size();
215	}
