12	void BinTree::loadDB()
13	{
14		for (int i=0; i < _context->getNumDatabaseFiles(); i++) {
15			FileRecordMgr *databaseFile = _context->getDatabaseFile(i);
16	
17			Record *record = NULL;
18			while (!databaseFile->eof()) {
19				record = databaseFile->getNextRecord();
20				//In addition to NULL records, we also don't want to add unmapped reads.
21				if (record == NULL || record->isUnmapped()) {
22					continue;
23				}
24	
25				_context->testNameConventions(record);
26	
27				if (!addRecordToTree(record)) {
28					fprintf(stderr, "ERROR: Unable to add record to tree.\n");
29					databaseFile->close();
30					exit(1);
31				}
32			}
33		}
34	}
