98	bool BinTree::addRecordToTree(Record *record)
99	{
100		// Get chr, bin.
101		const string &chr = record->getChrName();
102		binNumType startPos = (binNumType)(record->getStartPos());
103		binNumType endPos = (binNumType)(record->getEndPos());
104		binNumType binNum = getBin(startPos, endPos);
105	
106		if (binNum < 0 || binNum >= NUM_BINS) {
107			fprintf(stderr, "ERROR: Received illegal bin number %" PRId_BINNUMTYPE " from getBin call.\n"
108	                                "Maximum values is: %" PRId_BINNUMTYPE "\n"
109	                                "This typically means that your coordinates are\n"
110	                                "negative or too large to represent in the data\n"
111	                                "structure bedtools uses to find intersections.", binNum, NUM_BINS);
112			return false;
113		}
114		_mainMap[chr][binNum].push_back(record);
115		return true;
116	}
