120	void NewChromSweep::scanCache(int dbIdx, RecordKeyVector &retList) {
121	    recListIterType cacheIter = _caches[dbIdx].begin();
122	    while (cacheIter != _caches[dbIdx].end())
123	    {
124	        Record *cacheRec = cacheIter->value();
125	        if (_currQueryRec->sameChrom(cacheRec) && !_currQueryRec->after(cacheRec)) 
126	        {
127	            if (intersects(_currQueryRec, cacheRec)) 
128	            {
129	                retList.push_back(cacheRec);
130	            } 
131	            else if (cacheRec->after(_currQueryRec)) break; // cacheRec is after the query rec, stop scanning.
132	            cacheIter = _caches[dbIdx].next();
133	        }
134	        else 
135	        {
136	            _dbFRMs[dbIdx]->deleteRecord(cacheRec);
137	            cacheIter = _caches[dbIdx].deleteCurrent();
138	        }
139	    }
140	}
