188	bool NewChromSweep::chromChange(int dbIdx, RecordKeyVector &retList, bool wantScan)
189	{
190	    const Record *dbRec = _currDbRecs[dbIdx];
191	
192	    if (_currQueryRec != NULL && _currQueryChromName != _prevQueryChromName) {
193	        _context->testNameConventions(_currQueryRec);
194	        testChromOrder(_currQueryRec);
195	    }
196	
197	    if (dbRec != NULL) {
198	        _context->testNameConventions(dbRec);
199	        testChromOrder(dbRec);
