201	
202	    // If the query rec and db rec are on the same chrom, stop.
203	    if (dbRec != NULL && _currQueryRec != NULL && _currQueryRec->sameChrom(dbRec)) return false;
204	
205	
206	    if (dbRec == NULL || _currQueryRec == NULL) return false;
207	
208	    if (queryChromAfterDbRec(dbRec)) {
209	        // the query is ahead of the database. fast-forward the database to catch-up.
210	        string oldDbChrom(dbRec->getChrName());
211	        while (dbRec != NULL && queryChromAfterDbRec(dbRec)) 
212	        {
213	            _dbFRMs[dbIdx]->deleteRecord(dbRec);
214	            if (!nextRecord(false, dbIdx)) break;
215	            dbRec =  _currDbRecs[dbIdx];
216	            const string &newDbChrom = dbRec->getChrName();
217	            if (newDbChrom != oldDbChrom) {
218	                testChromOrder(dbRec);
219	                oldDbChrom = newDbChrom;
220	            }
221	        }
222	        clearCache(dbIdx);
223	        return false;
224	    } else {
225	        // the database is ahead of the query.
226	        // scan the cache for remaining hits on the query's current chrom.
227	        if (wantScan) scanCache(dbIdx, retList);
228	        return true;
229	    }
