412	bool NewChromSweep::verifyChromOrderMismatch(const string & chrom, const string &prevChrom, int skipFile) {
413	    //for every file except the one being checked,
414	    //find the current and previous chrom. If a given file
415	    //is missing either, skip it and go on. If it has both,
416	    //and the curr has a lower order num than the prev, return true.
417	
418	    //if that never happens, return false.
419	    for (int i=0; i < _numFiles; i++) {
420	        if (i == skipFile) continue;
421	        const _orderTrackType *track = _fileTracks[i];
422	        _orderTrackType::const_iterator iter = track->find(chrom);
423	        if (iter == track->end()) continue; //this file does not contain the curr chrom
424	        int currOrder = iter->second;
425	        iter = track->find(prevChrom);
426	        if (iter == track->end()) continue; //this file does not contain the prevChrom.
427	        int prevOrder = iter->second;
428	
429	        if (currOrder < prevOrder) return true;
430	    }
431	    return false;
432	}
